-- ---------------------------------------------------------------------
-- 11. Blueprint: stored source, sections and tasks
-- ---------------------------------------------------------------------
create table desk.blueprint_documents (
  id               uuid primary key default gen_random_uuid(),
  version          int not null unique,
  title            text not null,
  doc_date         date,                -- from the byline, e.g. 14 Nov 2026; sets the run-sheet year
  source_markdown  text not null,       -- kept whole for the Phase 2 Docs module
  sha256           text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  is_current       boolean not null default false,
  imported_at      timestamptz not null default now(),
  imported_by      uuid
);
create unique index blueprint_one_current on desk.blueprint_documents (is_current) where is_current;

create table desk.blueprint_sections (
  id             uuid primary key default gen_random_uuid(),
  key            text not null unique,  -- slug path, e.g. "10-december-run-sheet-day-by-day/tue-1-dec"
  parent_id      uuid references desk.blueprint_sections (id),
  level          smallint not null check (level between 1 and 6),
  number         text,                  -- "10" from "## 10. December run sheet"
  title          text not null,
  position       int not null,
  run_date       date,                  -- set for run-sheet day headings, e.g. 2026-12-01
  body_markdown  text not null default '',  -- prose and tables, without the checklist
  document_id    uuid references desk.blueprint_documents (id),  -- last version that contained it
  removed_at     timestamptz            -- gone from the latest import; kept for history
);

create table desk.tasks (
  id             uuid primary key default gen_random_uuid(),
  kind           text not null check (kind in ('blueprint', 'adhoc')),
  title          text not null check (char_length(title) between 1 and 1000),
  section_id     uuid references desk.blueprint_sections (id),
  section_label  text,          -- free label for ad hoc tasks
  source_ref     text,          -- readable heading path, e.g. "10. December run sheet > Tue 1 Dec"
  match_key      text,          -- section key + normalised text + occurrence; how re-import keeps ticks
  position       int,
  due_date       date,
  done_at        timestamptz,
  done_by        uuid,
  lead_id        uuid references desk.leads (id),   -- ad hoc follow-up tied to a lead
  removed_at     timestamptz,   -- dropped by a re-import; tick history kept
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  created_by     uuid,
  check (kind <> 'blueprint' or (section_id is not null and match_key is not null))
);
create unique index tasks_match_key_uq on desk.tasks (match_key)
  where kind = 'blueprint' and removed_at is null;
create index tasks_due_idx     on desk.tasks (due_date) where done_at is null and removed_at is null;
create index tasks_section_idx on desk.tasks (section_id, position);


-- >>> 0007_scorecard.sql
-- ---------------------------------------------------------------------
-- 12. Targets and the weekly scorecard
-- ---------------------------------------------------------------------
create table desk.targets (
  id            uuid primary key default gen_random_uuid(),
  kind          text not null check (kind in ('channel', 'weekly')),
  metric_key    text not null check (metric_key ~ '^[a-z][a-z0-9_]{1,60}$'),
  label         text not null,
  channel_key   text references desk.channels (key),
  period_start  date not null,      -- channel: the period; weekly: in force from this Monday
  period_end    date,               -- null = open-ended
  unit          text not null check (unit in ('count', 'hours', 'cents', 'milestone')),
  target_value  numeric(12, 2),     -- count / hours / milestone (1 = done)
  target_cents  bigint,             -- money targets only
  cap_value     numeric(12, 2),     -- e.g. hours: target 8, cap 10
  due_date      date,               -- milestones, e.g. BOQ Checker live by 8 Dec
  count_source  text not null check (count_source in ('leads', 'stage_history', 'manual')),
  source_filter jsonb not null default '{}',  -- {"source_key": "linkedin_search_e"} or {"to_stage": "audit_booked"}
  sort_order    int not null default 0,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (kind <> 'channel' or channel_key is not null),
  check (unit = 'cents' or target_cents is null),
  check (unit <> 'cents' or target_value is null),
  unique nulls not distinct (kind, metric_key, channel_key, period_start)
);

create table desk.scorecard_entries (
  id            uuid primary key default gen_random_uuid(),
  target_id     uuid not null references desk.targets (id),
  period_start  date not null,      -- Monday of the SAST week, or the channel target's period start
  value         numeric(12, 2),
  value_cents   bigint,
  note          text check (char_length(note) <= 500),
  entered_by    uuid,
  entered_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (target_id, period_start),
  check (num_nonnulls(value, value_cents) = 1)
);


-- >>> 0008_platforms.sql
-- ---------------------------------------------------------------------
-- 13. Platforms register (no secrets, ever)
-- ---------------------------------------------------------------------
create table desk.platforms (
  id                  uuid primary key default gen_random_uuid(),
  name                text not null unique check (char_length(name) between 1 and 100),
  purpose             text check (char_length(purpose) <= 300),
  url                 text check (url ~* '^https://'),
  monthly_cost_cents  bigint check (monthly_cost_cents >= 0),  -- null = not set yet (shown, not counted)
  billing_cycle       text not null default 'monthly' check (billing_cycle in ('monthly', 'annual', 'usage', 'free', 'once')),
  renewal_date        date,
  auto_advance        boolean not null default true,   -- roll renewal_date forward one cycle once it passes
  login_location      text check (char_length(login_location) <= 200),
  owner_email         extensions.citext,
  status              text not null default 'active' check (status in ('active', 'planned', 'deciding', 'paused', 'cancelled')),
  is_reminder         boolean not null default false,  -- e.g. "Monthly backup export", not a paid tool
  notes               text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  -- A hint like "Bitwarden: Aurion > Vercel" is fine. Things that look like secrets are refused.
  constraint platforms_login_location_not_secret check (
    login_location is null or (
      login_location !~* '(password|passwd|pwd|secret|token|api[ _-]?key)\s*[:=]'
      and login_location !~ '[A-Za-z0-9_\-]{24,}'
      and login_location !~* '(sk|pk|rk)[-_](live|test|ant)'
    ))
);


