-- >>> 0012_pipeline_functions.sql
-- ---------------------------------------------------------------------
-- 0012 Pipeline: event triggers, the atomic CSV import, a fallback contact method.
-- ---------------------------------------------------------------------

insert into desk.contact_methods (key, label, sort_order) values ('other', 'Other or unknown', 99)
on conflict (key) do nothing;

-- Every consent record writes an event (subject: the contact).
create or replace function desk.tg_consent_event()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
  values (desk.current_event_source(), 'consent_recorded', 'contact', new.contact_id::text, auth.uid(),
          jsonb_build_object('status', new.status, 'method', new.method_key, 'evidence', new.evidence_type));
  return null;
end $$;
create trigger consent_event_tg after insert on desk.consent_records
  for each row execute function desk.tg_consent_event();

-- Every logged activity writes an event (subject: the lead if there is one, else the contact).
create or replace function desk.tg_activity_event()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into desk.events (source, type, subject_type, subject_id, actor_id, occurred_at, payload)
  values (desk.current_event_source(), 'activity_logged',
          case when new.lead_id is not null then 'lead' else 'contact' end,
          coalesce(new.lead_id, new.contact_id)::text, auth.uid(), new.occurred_at,
          jsonb_build_object('method', new.method_key, 'direction', new.direction, 'purpose', new.purpose_key));
  return null;
end $$;
create trigger activity_event_tg after insert on desk.activities
  for each row execute function desk.tg_activity_event();

/*
 * The CSV import commit. p_rows is the validated, normalised output of the dry run
 * (src/modules/pipeline/csv-import.ts). It runs as the signed-in user (RLS applies) and in a
 * single transaction: either every row lands or none does.
 *
 * Row keys: row, firm, type_key, town, website, domain, contact_name, role_title, linkedin_url,
 * email, source_key, first_contact_date, channel_key, consent_status, consent_raw,
 * consent_method, stage_key, next_action, next_date, notes
 */
create or replace function desk.import_pipeline(p_batch_id uuid, p_rows jsonb)
returns jsonb language plpgsql set search_path = '' as $$
declare
  r          jsonb;
  v_org      uuid;
  v_contact  uuid;
  v_leads    int := 0;
  v_skipped  int := 0;
  v_consents int := 0;
  v_orgs     int := 0;
begin
  if not desk.can('pipeline.import') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if not exists (select 1 from desk.import_batches where id = p_batch_id and status = 'dry_run' and kind = 'pipeline_csv') then
    raise exception 'Run the dry run again before importing.' using errcode = 'DK010';
  end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    v_org := null;
    v_contact := null;

    -- A contact already in Desk (same email) is skipped, never overwritten.
    if nullif(r ->> 'email', '') is not null
       and exists (select 1 from desk.contacts where email = (r ->> 'email')) then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    if nullif(r ->> 'firm', '') is not null then
      select id into v_org from desk.organisations
       where lower(name) = lower(r ->> 'firm')
         and coalesce(lower(town), '') = coalesce(lower(nullif(r ->> 'town', '')), coalesce(lower(town), ''))
       order by created_at limit 1;
      if v_org is null then
        insert into desk.organisations (name, type_key, town, website, domain, created_by)
        values (r ->> 'firm', nullif(r ->> 'type_key', ''), nullif(r ->> 'town', ''), nullif(r ->> 'website', ''),
                nullif(r ->> 'domain', ''), auth.uid())
        returning id into v_org;
        v_orgs := v_orgs + 1;
      end if;
    end if;

    if coalesce(nullif(r ->> 'contact_name', ''), nullif(r ->> 'email', ''), nullif(r ->> 'linkedin_url', '')) is not null then
      insert into desk.contacts (organisation_id, full_name, role_title, email, linkedin_url, created_by)
      values (v_org, nullif(r ->> 'contact_name', ''), nullif(r ->> 'role_title', ''), nullif(r ->> 'email', ''),
              nullif(r ->> 'linkedin_url', ''), auth.uid())
      returning id into v_contact;
    end if;

    insert into desk.leads (contact_id, organisation_id, source_key, channel_key, stage_key, first_contact_date,
                            next_action, next_date, notes, created_from, owner_id, created_by)
    values (v_contact, v_org, nullif(r ->> 'source_key', ''), nullif(r ->> 'channel_key', ''),
            coalesce(nullif(r ->> 'stage_key', ''), 'new'), nullif(r ->> 'first_contact_date', '')::date,
            nullif(r ->> 'next_action', ''), nullif(r ->> 'next_date', '')::date, nullif(r ->> 'notes', ''),
            'import', auth.uid(), auth.uid());
    v_leads := v_leads + 1;

    if v_contact is not null and nullif(r ->> 'consent_status', '') is not null then
      insert into desk.consent_records (contact_id, status, method_key, wording_shown, evidence_type, evidence_ref, recorded_by)
      values (v_contact, r ->> 'consent_status', coalesce(nullif(r ->> 'consent_method', ''), 'other'),
              'Imported from the Aurion Pipeline tracker. Consent column: ' || coalesce(r ->> 'consent_raw', ''),
              'import', p_batch_id::text, auth.uid());
      v_consents := v_consents + 1;
    end if;
  end loop;

  update desk.import_batches
     set status = 'committed', committed_at = now(),
         report = report || jsonb_build_object('committed', jsonb_build_object(
           'leads', v_leads, 'skipped', v_skipped, 'consents', v_consents, 'organisations', v_orgs))
   where id = p_batch_id;

  insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
  values ('import', 'pipeline_imported', 'import_batch', p_batch_id::text, auth.uid(),
          jsonb_build_object('leads', v_leads, 'skipped', v_skipped, 'consents', v_consents, 'organisations', v_orgs));

  return jsonb_build_object('leads', v_leads, 'skipped', v_skipped, 'consents', v_consents, 'organisations', v_orgs);
end $$;

revoke all on function desk.import_pipeline(uuid, jsonb) from public, anon;
grant execute on function desk.import_pipeline(uuid, jsonb) to authenticated, service_role;

/*
 * Quick add: organisation (reused by name), contact (deduped on email, then phone) and lead,
 * in one transaction. If the person already has an open lead, nothing is created and that
 * lead is returned with existing = true.
 * Keys: name, firm, email, phone, channel_key, source_key, next_action, next_date, first_contact_date
 */
create or replace function desk.quick_add_lead(p jsonb)
returns jsonb language plpgsql set search_path = '' as $$
declare
  v_org     uuid;
  v_contact uuid;
  v_lead    uuid;
begin
  if not desk.can('pipeline.write') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  if nullif(p ->> 'email', '') is not null then
    select id into v_contact from desk.contacts where email = (p ->> 'email');
  end if;
  if v_contact is null and nullif(p ->> 'phone', '') is not null then
    select id into v_contact from desk.contacts where phone_e164 = (p ->> 'phone');
  end if;

  if v_contact is not null then
    select id into v_lead from desk.leads where contact_id = v_contact and archived_at is null;
    if v_lead is not null then
      return jsonb_build_object('lead_id', v_lead, 'existing', true);
    end if;
    select organisation_id into v_org from desk.contacts where id = v_contact;
  end if;

  if v_org is null and nullif(p ->> 'firm', '') is not null then
    select id into v_org from desk.organisations where lower(name) = lower(p ->> 'firm') order by created_at limit 1;
    if v_org is null then
      insert into desk.organisations (name, created_by) values (p ->> 'firm', auth.uid()) returning id into v_org;
    end if;
  end if;

  if v_contact is null and coalesce(nullif(p ->> 'name', ''), nullif(p ->> 'email', ''), nullif(p ->> 'phone', '')) is not null then
    insert into desk.contacts (organisation_id, full_name, email, phone_e164, created_by)
    values (v_org, nullif(p ->> 'name', ''), nullif(p ->> 'email', ''), nullif(p ->> 'phone', ''), auth.uid())
    returning id into v_contact;
  end if;

  insert into desk.leads (contact_id, organisation_id, channel_key, source_key, next_action, next_date,
                          first_contact_date, created_from, owner_id, created_by)
  values (v_contact, v_org, nullif(p ->> 'channel_key', ''), nullif(p ->> 'source_key', ''),
          nullif(p ->> 'next_action', ''), nullif(p ->> 'next_date', '')::date,
          coalesce(nullif(p ->> 'first_contact_date', '')::date, desk.today_sast()),
          'manual', auth.uid(), auth.uid())
  returning id into v_lead;

  return jsonb_build_object('lead_id', v_lead, 'existing', false);
end $$;

revoke all on function desk.quick_add_lead(jsonb) from public, anon;
grant execute on function desk.quick_add_lead(jsonb) to authenticated;

-- The export needs the organisation's website; appended as the last column of the read model.
create or replace view desk.lead_overview with (security_invoker = true) as
  select
    l.*,
    c.full_name, c.email, c.phone_e164, c.role_title, c.linkedin_url, c.forgotten_at,
    o.name  as organisation_name, o.type_key as organisation_type, o.town,
    cc.status as consent_status,
    coalesce(cc.status = 'no', false) as do_not_contact,
    (l.next_date is not null and l.next_date < desk.today_sast()
       and not s.is_closed) as is_overdue,
    s.position as stage_position,
    o.website as organisation_website
  from desk.leads l
  join desk.stages s on s.key = l.stage_key
  left join desk.contacts c on c.id = l.contact_id
  left join desk.organisations o on o.id = coalesce(l.organisation_id, c.organisation_id)
  left join desk.contact_consent_current cc on cc.contact_id = l.contact_id;


-- >>> 0013_inbox_functions.sql
-- ---------------------------------------------------------------------
-- 0013 Inbox: ingest (service role), accept and dismiss (members), notification claims.
-- ---------------------------------------------------------------------

/*
 * Called only by the ingest endpoints (service role). One transaction:
 *   - drop exact repeats (same dedupe_key) and report them as duplicates;
 *   - find the contact by email, then phone; fill in blanks, never overwrite;
 *   - create the organisation and contact when new;
 *   - add the inbox item;
 *   - record consent ONLY when the visitor explicitly ticked it (evidence: form id or transcript id);
 *   - write form_submitted / chatbot_lead_received.
 * Keys: source, dedupe_key, name, company, email, phone, message, form_id, page_url, need, offer,
 *       score, score_reason, transcript_id, consent_ticked, consent_wording, suppressed, payload
 */
create or replace function desk.ingest_lead(p jsonb)
returns jsonb language plpgsql set search_path = '' as $$
declare
  v_existing uuid;
  v_contact  uuid;
  v_org      uuid;
  v_item     uuid;
  v_source   text := p ->> 'source';
  v_said_no  boolean := false;
begin
  if v_source not in ('form', 'chatbot') then
    raise exception 'unknown source %', v_source using errcode = '22023';
  end if;

  select id into v_existing from desk.inbox_items where dedupe_key = p ->> 'dedupe_key';
  if v_existing is not null then
    return jsonb_build_object('inbox_item_id', v_existing, 'duplicate', true);
  end if;

  if nullif(p ->> 'email', '') is not null then
    select id, organisation_id into v_contact, v_org from desk.contacts where email = (p ->> 'email');
  end if;
  if v_contact is null and nullif(p ->> 'phone', '') is not null then
    select id, organisation_id into v_contact, v_org from desk.contacts where phone_e164 = (p ->> 'phone');
  end if;

  if v_org is null and nullif(p ->> 'company', '') is not null then
    select id into v_org from desk.organisations where lower(name) = lower(p ->> 'company') order by created_at limit 1;
    if v_org is null then
      insert into desk.organisations (name) values (left(p ->> 'company', 200)) returning id into v_org;
    end if;
  end if;

  if v_contact is null then
    insert into desk.contacts (organisation_id, full_name, email, phone_e164)
    values (v_org, nullif(left(p ->> 'name', 200), ''), nullif(p ->> 'email', ''), nullif(p ->> 'phone', ''))
    returning id into v_contact;
  else
    -- fill blanks only; a phone or email already used by someone else is left alone
    update desk.contacts c
       set full_name = coalesce(c.full_name, nullif(left(p ->> 'name', 200), '')),
           organisation_id = coalesce(c.organisation_id, v_org),
           email = case when c.email is null and nullif(p ->> 'email', '') is not null
                         and not exists (select 1 from desk.contacts x where x.email = (p ->> 'email'))
                        then p ->> 'email' else c.email end,
           phone_e164 = case when c.phone_e164 is null and nullif(p ->> 'phone', '') is not null
                              and not exists (select 1 from desk.contacts x where x.phone_e164 = (p ->> 'phone'))
                             then p ->> 'phone' else c.phone_e164 end
     where c.id = v_contact and c.forgotten_at is null;
    v_said_no := coalesce(desk.contact_consent_status(v_contact) = 'no', false);
  end if;

  insert into desk.inbox_items (source, contact_id, organisation_id, name, company, email, phone_e164, message,
                                form_id, page_url, need, offer, score, score_reason, transcript_id,
                                consent_ticked, consent_wording, suppressed, payload, dedupe_key)
  values (v_source, v_contact, v_org, nullif(p ->> 'name', ''), nullif(p ->> 'company', ''), nullif(p ->> 'email', ''),
          nullif(p ->> 'phone', ''), nullif(p ->> 'message', ''), nullif(p ->> 'form_id', ''), nullif(p ->> 'page_url', ''),
          nullif(p ->> 'need', ''), nullif(p ->> 'offer', ''), nullif(p ->> 'score', '')::smallint,
          nullif(p ->> 'score_reason', ''), nullif(p ->> 'transcript_id', ''),
          coalesce((p ->> 'consent_ticked')::boolean, false), nullif(p ->> 'consent_wording', ''),
          coalesce((p ->> 'suppressed')::boolean, false) or v_said_no,
          coalesce(p -> 'payload', '{}'::jsonb), p ->> 'dedupe_key')
  returning id into v_item;

  insert into desk.events (source, type, subject_type, subject_id, idempotency_key, payload)
  values (v_source, case v_source when 'form' then 'form_submitted' else 'chatbot_lead_received' end,
          'inbox_item', v_item::text, p ->> 'dedupe_key',
          jsonb_build_object('form_id', p ->> 'form_id', 'score', p ->> 'score', 'offer', p ->> 'offer',
                             'consent_ticked', coalesce((p ->> 'consent_ticked')::boolean, false)));

  -- Consent is recorded only for an explicit tick. A visitor who once said no and now ticks
  -- "yes" has asked us in writing to contact them: that new record becomes their current one.
  if coalesce((p ->> 'consent_ticked')::boolean, false) and nullif(p ->> 'consent_wording', '') is not null then
    insert into desk.consent_records (contact_id, status, method_key, wording_shown, evidence_type, evidence_ref)
    values (v_contact, 'yes', case v_source when 'form' then 'website_form' else 'chatbot' end,
            p ->> 'consent_wording',
            case v_source when 'form' then 'form' else 'chat_transcript' end,
            coalesce(nullif(p ->> 'transcript_id', ''), nullif(p ->> 'form_id', ''), v_item::text));
  end if;

  return jsonb_build_object('inbox_item_id', v_item, 'contact_id', v_contact, 'duplicate', false,
                            'suppressed', coalesce((p ->> 'suppressed')::boolean, false) or v_said_no);
end $$;

revoke all on function desk.ingest_lead(jsonb) from public, anon, authenticated;
grant execute on function desk.ingest_lead(jsonb) to service_role;

/*
 * Accept an inbox item into the pipeline. Reuses the contact's open lead if there is one.
 */
create or replace function desk.accept_inbox_item(p_id uuid, p_channel_key text, p_source_key text)
returns jsonb language plpgsql set search_path = '' as $$
declare
  i       desk.inbox_items%rowtype;
  v_lead  uuid;
  v_new   boolean := false;
  v_notes text;
begin
  if not (desk.can('inbox.decide') and desk.can('pipeline.write')) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  select * into i from desk.inbox_items where id = p_id for update;
  if not found then raise exception 'No such inbox item' using errcode = 'P0002'; end if;
  if i.status <> 'new' then raise exception 'This item was already handled.' using errcode = 'DK011'; end if;

  if i.contact_id is not null then
    select id into v_lead from desk.leads where contact_id = i.contact_id and archived_at is null;
  end if;

  v_notes := concat_ws(E'\n',
    case i.source when 'form' then 'From the website form' || coalesce(' (' || i.form_id || ')', '') else 'From the website chatbot' end
      || ' on ' || to_char(i.received_at at time zone 'Africa/Johannesburg', 'DD Mon YYYY') || '.',
    'Message: ' || i.message,
    'Need: ' || i.need,
    'Offer: ' || i.offer,
    'Score reason: ' || i.score_reason);

  if v_lead is null then
    insert into desk.leads (contact_id, organisation_id, source_key, channel_key, first_contact_date, score, notes,
                            next_date, created_from, owner_id, created_by)
    values (i.contact_id, i.organisation_id, p_source_key, p_channel_key,
            (i.received_at at time zone 'Africa/Johannesburg')::date, i.score, v_notes,
            desk.today_sast() + 1, i.source, auth.uid(), auth.uid())
    returning id into v_lead;
    v_new := true;
  else
    update desk.leads
       set score = coalesce(i.score, score),
           notes = concat_ws(E'\n\n', notes, v_notes)
     where id = v_lead;
  end if;

  update desk.inbox_items
     set status = 'accepted', lead_id = v_lead, decided_at = now(), decided_by = auth.uid()
   where id = p_id;

  insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
  values ('manual', 'inbox_accepted', 'inbox_item', p_id::text, auth.uid(),
          jsonb_build_object('lead_id', v_lead, 'new_lead', v_new));

  return jsonb_build_object('lead_id', v_lead, 'new_lead', v_new);
end $$;

create or replace function desk.dismiss_inbox_item(p_id uuid, p_reason text)
returns void language plpgsql set search_path = '' as $$
begin
  if not desk.can('inbox.decide') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Give a reason.' using errcode = '23514';
  end if;
  update desk.inbox_items
     set status = 'dismissed', dismiss_reason = left(trim(p_reason), 300), decided_at = now(), decided_by = auth.uid()
   where id = p_id and status = 'new';
  if not found then raise exception 'This item was already handled.' using errcode = 'DK011'; end if;
  insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
  values ('manual', 'inbox_dismissed', 'inbox_item', p_id::text, auth.uid(), jsonb_build_object('reason', left(trim(p_reason), 300)));
end $$;

revoke all on function desk.accept_inbox_item(uuid, text, text), desk.dismiss_inbox_item(uuid, text) from public, anon;
grant execute on function desk.accept_inbox_item(uuid, text, text), desk.dismiss_inbox_item(uuid, text) to authenticated;

/*
 * Claim a notification before sending it. Returns true only for the first claim of a key
 * (or a retry of one that failed), so running a job twice never sends twice.
 */
create or replace function desk.claim_notification(p_key text, p_channel text, p_subject text, p_job_run uuid default null)
returns boolean language plpgsql set search_path = '' as $$
declare
  v_id uuid;
begin
  insert into desk.notifications (dedupe_key, channel, subject, job_run_id)
  values (p_key, p_channel, p_subject, p_job_run)
  on conflict (dedupe_key) do update
     set status = 'claimed', claimed_at = now(), error = null, job_run_id = excluded.job_run_id
   where desk.notifications.status = 'failed'
  returning id into v_id;
  return v_id is not null;
end $$;

revoke all on function desk.claim_notification(text, text, text, uuid) from public, anon, authenticated;
grant execute on function desk.claim_notification(text, text, text, uuid) to service_role;

-- Resend sends Desk's alerts and digest (its sender domain is already verified for aurion-assistant).
insert into desk.platforms (name, purpose, url, billing_cycle, status, notes) values
  ('Resend', 'Desk alerts and daily digest; aurion-assistant alert emails', 'https://resend.com', 'monthly', 'active',
   'Sender domain aurioncreative.com is shared with aurion-assistant')
on conflict (name) do nothing;


-- >>> 0014_blueprint_functions.sql
-- ---------------------------------------------------------------------
-- 0014 Blueprint: apply an import (keeping ticks), and events for ticking tasks.
-- ---------------------------------------------------------------------

/*
 * Applies a parsed blueprint in one transaction. p is built by applyPayload() in
 * src/modules/blueprint/diff.ts after you have seen the diff:
 *   expected_version  the version the diff was computed against (stops a stale apply)
 *   doc               title, doc_date, source_markdown, sha256
 *   sections[]        key, parent_key, level, number, title, position, run_date, body_markdown
 *   tasks[]           match_key, section_key, title, position, due_date, source_ref
 *   renames[]         id, match_key: existing tasks (reworded or restored) that take a new key
 * Ticks (done_at) are never touched here.
 */
create or replace function desk.apply_blueprint(p jsonb)
returns jsonb language plpgsql set search_path = '' as $$
declare
  v_current int;
  v_version int;
  v_doc     uuid;
  s         jsonb;
  t         jsonb;
  r         jsonb;
  v_section uuid;
  v_task    uuid;
  v_added   int := 0;
  v_updated int := 0;
  v_removed int := 0;
begin
  if not (desk.can('blueprint.import') and desk.can('blueprint.write')) then
    raise exception 'Not allowed' using errcode = '42501';
  end if;

  select version into v_current from desk.blueprint_documents where is_current;
  if v_current is distinct from (p ->> 'expected_version')::int then
    raise exception 'The blueprint changed since this diff was made. Upload it again.' using errcode = 'DK012';
  end if;
  v_version := coalesce((select max(version) from desk.blueprint_documents), 0) + 1;

  update desk.blueprint_documents set is_current = false where is_current;
  insert into desk.blueprint_documents (version, title, doc_date, source_markdown, sha256, is_current, imported_by)
  values (v_version, p -> 'doc' ->> 'title', nullif(p -> 'doc' ->> 'doc_date', '')::date,
          p -> 'doc' ->> 'source_markdown', p -> 'doc' ->> 'sha256', true, auth.uid())
  returning id into v_doc;

  -- Sections: upsert by key (parents come first in document order).
  for s in select * from jsonb_array_elements(p -> 'sections') loop
    insert into desk.blueprint_sections (key, parent_id, level, number, title, position, run_date, body_markdown, document_id, removed_at)
    values (s ->> 'key',
            (select id from desk.blueprint_sections where key = s ->> 'parent_key'),
            (s ->> 'level')::smallint, nullif(s ->> 'number', ''), s ->> 'title', (s ->> 'position')::int,
            nullif(s ->> 'run_date', '')::date, coalesce(s ->> 'body_markdown', ''), v_doc, null)
    on conflict (key) do update
       set parent_id = excluded.parent_id, level = excluded.level, number = excluded.number,
           title = excluded.title, position = excluded.position, run_date = excluded.run_date,
           body_markdown = excluded.body_markdown, document_id = v_doc, removed_at = null;
  end loop;
  update desk.blueprint_sections set removed_at = now()
   where removed_at is null and key not in (select x ->> 'key' from jsonb_array_elements(p -> 'sections') x);

  -- Reworded and restored tasks take their new key first, keeping their tick.
  for r in select * from jsonb_array_elements(coalesce(p -> 'renames', '[]'::jsonb)) loop
    update desk.tasks set match_key = r ->> 'match_key', removed_at = null
     where id = (r ->> 'id')::uuid and kind = 'blueprint';
  end loop;

  for t in select * from jsonb_array_elements(p -> 'tasks') loop
    select id into v_section from desk.blueprint_sections where key = t ->> 'section_key';
    select id into v_task from desk.tasks where kind = 'blueprint' and match_key = t ->> 'match_key' and removed_at is null;
    if v_task is null then
      insert into desk.tasks (kind, title, section_id, source_ref, match_key, position, due_date, created_by)
      values ('blueprint', t ->> 'title', v_section, t ->> 'source_ref', t ->> 'match_key', (t ->> 'position')::int,
              nullif(t ->> 'due_date', '')::date, auth.uid());
      v_added := v_added + 1;
    else
      update desk.tasks
         set title = t ->> 'title', section_id = v_section, source_ref = t ->> 'source_ref',
             position = (t ->> 'position')::int, due_date = nullif(t ->> 'due_date', '')::date
       where id = v_task;
      v_updated := v_updated + 1;
    end if;
  end loop;

  update desk.tasks set removed_at = now()
   where kind = 'blueprint' and removed_at is null
     and match_key not in (select x ->> 'match_key' from jsonb_array_elements(p -> 'tasks') x);
  get diagnostics v_removed = row_count;

  insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
  values ('import', 'blueprint_imported', 'blueprint_document', v_doc::text, auth.uid(),
          jsonb_build_object('version', v_version, 'added', v_added, 'updated', v_updated, 'removed', v_removed));

  return jsonb_build_object('version', v_version, 'added', v_added, 'updated', v_updated, 'removed', v_removed);
end $$;

revoke all on function desk.apply_blueprint(jsonb) from public, anon;
grant execute on function desk.apply_blueprint(jsonb) to authenticated;

-- Ticking and unticking a task writes an event (task_done / task_reopened).
create or replace function desk.tg_task_event()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.done_at is distinct from old.done_at then
    insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
    values (desk.current_event_source(), case when new.done_at is null then 'task_reopened' else 'task_done' end,
            'task', new.id::text, auth.uid(), jsonb_build_object('kind', new.kind, 'due_date', new.due_date));
  end if;
  return null;
end $$;
create trigger tasks_event_tg after update of done_at on desk.tasks
  for each row execute function desk.tg_task_event();

create or replace function desk.tg_task_created_event()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.kind = 'adhoc' then
    insert into desk.events (source, type, subject_type, subject_id, actor_id, payload)
    values (desk.current_event_source(), 'task_created', 'task', new.id::text, auth.uid(), jsonb_build_object('due_date', new.due_date));
  end if;
  return null;
end $$;
create trigger tasks_created_event_tg after insert on desk.tasks
  for each row execute function desk.tg_task_created_event();


-- >>> 0015_scorecard_and_events.sql
-- ---------------------------------------------------------------------
-- 0015 Events default their actor to the signed-in user (service-role writes stay null),
-- so every event a member's action writes passes the "actor is you" insert policy.
-- ---------------------------------------------------------------------
alter table desk.events alter column actor_id set default auth.uid();

-- Two more audit actions for account changes made in Settings.
alter table desk.audit_log drop constraint audit_log_action_check;
alter table desk.audit_log add constraint audit_log_action_check check (action in (
  'create', 'update', 'delete',
  'sign_in', 'sign_in_failed', 'sign_in_locked', 'sign_out',
  'mfa_enrolled', 'mfa_verified', 'mfa_failed', 'mfa_removed', 'password_changed', 'session_expired',
  'export', 'forget', 'import'));
